const listEvents = `-- name: ListEvents :many
SELECT 
    e.id, e.organizer_id, e.title, e.description, e.category, e.status, 
    e.banner_url, e.google_place_id, e.location_name, e.city, e.vibe, e.organizer_absorbs_service_fee, e.vat_percentage, e.external_ticket_url, e.latitude, e.longitude, e.start_time,
    e.end_time, e.is_live, e.created_at,
    
    (
        SELECT COUNT(*) 
        FROM check_ins 
        WHERE event_id = e.id
    )::bigint AS total_check_ins,
    
    EXISTS(
        SELECT 1 
        FROM check_ins 
        WHERE check_ins.event_id = e.id 
          AND check_ins.user_id = $1
    ) AS user_has_checked_in,
    EXISTS(
        SELECT 1
        FROM saved_events
        WHERE saved_events.event_id = e.id
          AND saved_events.user_id = $1
    ) AS is_favorited,
    
    COALESCE(
        (
            SELECT json_agg(
                json_build_object(
                    'id', tt.id,
                    'name', tt.name,
                    'price_ron', tt.price_ron,
                    'capacity', tt.capacity,
                    'tickets_sold', tt.tickets_sold,
                    'start_sales', tt.start_sales,
                    'end_sales', tt.end_sales,
                    'description', tt.description
                )
            )
            FROM ticket_types tt
            WHERE tt.event_id = e.id
        ), 
        '[]'::json
    ) AS ticket_types,
    COALESCE(
        (
            SELECT json_agg(
                json_build_object(
                    'id', artist.id,
                    'name', artist.name,
                    'image_url', COALESCE(artist.image_url, ''),
                    'stage', artist.stage,
                    'performance_time', artist.performance_time,
                    'spotify_url', artist.spotify_url,
                    'is_headliner', artist.is_headliner,
                    'source', artist.source
                ) ORDER BY artist.sort_order, artist.created_at
            )
            FROM event_artists artist
            WHERE artist.event_id = e.id
        ),
        '[]'::json
    ) AS lineup
FROM events e
WHERE ($2::VARCHAR = '' OR $2 IS NULL OR e.category = ANY(string_to_array($2::VARCHAR, ',')))
  AND ($3::VARCHAR = '' OR $3 IS NULL OR e.city = $3)
  AND ($4::VARCHAR = '' OR $4 IS NULL OR e.vibe = ANY(string_to_array($4::VARCHAR, ',')))
  AND ($5::TIMESTAMPTZ IS NULL OR e.end_time > $5)
  AND ($6::TIMESTAMPTZ IS NULL OR e.start_time < $6)
  -- Filtre geolocație cu nume clare
  AND ($7::FLOAT IS NULL OR e.latitude BETWEEN $7 AND $8)
  AND ($9::FLOAT IS NULL OR e.longitude BETWEEN $9 AND $10)
  -- Filtru ID specific
  AND ($11::UUID IS NULL OR e.id = $11)
  -- Filtru organizator pentru profilul public
  AND ($12::UUID IS NULL OR e.organizer_id = $12)
  AND NOT EXISTS (
      SELECT 1 FROM user_hidden_event_categories hidden
      WHERE hidden.user_id = $1 AND hidden.category = UPPER(e.category)
  )
  AND (
      e.status = 'published'
      OR (
          $12::UUID IS NOT NULL
          AND e.status = 'completed'
          AND e.was_published = TRUE
      )
  )
ORDER BY e.start_time DESC
LIMIT $14 OFFSET $13
`

type ListEventsParams struct {
	UserID       pgtype.UUID        `json:"user_id"`
	Category     string             `json:"category"`
	City         string             `json:"city"`
	Vibe         string             `json:"vibe"`
	StartsAfter  pgtype.Timestamptz `json:"starts_after"`
	StartsBefore pgtype.Timestamptz `json:"starts_before"`
	LatMin       pgtype.Float8      `json:"lat_min"`
	LatMax       pgtype.Float8      `json:"lat_max"`
	LonMin       pgtype.Float8      `json:"lon_min"`
	LonMax       pgtype.Float8      `json:"lon_max"`
	EventID      pgtype.UUID        `json:"event_id"`
	OrganizerID  pgtype.UUID        `json:"organizer_id"`
	ReqOffset    int32              `json:"req_offset"`
	ReqLimit     int32              `json:"req_limit"`
}

