func (q *Queries) ListEvents(ctx context.Context, arg ListEventsParams) ([]ListEventsRow, error) {
	rows, err := q.db.Query(ctx, listEvents,
		arg.UserID,
		arg.Category,
		arg.City,
		arg.Vibe,
		arg.StartsAfter,
		arg.StartsBefore,
		arg.LatMin,
		arg.LatMax,
		arg.LonMin,
		arg.LonMax,
		arg.EventID,
		arg.OrganizerID,
		arg.ReqOffset,
		arg.ReqLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListEventsRow
	for rows.Next() {
		var i ListEventsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizerID,
			&i.Title,
			&i.Description,
			&i.Category,
			&i.Status,
			&i.BannerUrl,
			&i.GooglePlaceID,
			&i.LocationName,
			&i.City,
			&i.Vibe,
			&i.OrganizerAbsorbsServiceFee,
			&i.VatPercentage,
			&i.ExternalTicketUrl,
			&i.Latitude,
			&i.Longitude,
			&i.StartTime,
			&i.EndTime,
			&i.IsLive,
			&i.CreatedAt,
			&i.TotalCheckIns,
			&i.UserHasCheckedIn,
			&i.IsFavorited,
			&i.TicketTypes,
			&i.Lineup,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listEventsWithStats = `-- name: ListEventsWithStats :many
SELECT 
    e.id, e.organizer_id, e.title, e.description, e.category, e.banner_url, e.location_address, e.location_name, e.city, e.vibe, e.latitude, e.longitude, e.start_time, e.end_time, e.is_live, e.created_at, e.google_place_id, e.status, e.organizer_absorbs_service_fee, e.publish_at, e.was_published, e.vat_percentage, e.external_ticket_url,
    (
        SELECT COUNT(*)::bigint 
        FROM check_ins 
        WHERE event_id = e.id
    ) AS total_check_ins,
    COALESCE(SUM(tt.tickets_sold), 0)::bigint AS total_tickets_sold,
    COALESCE((
        SELECT SUM(oi.quantity::bigint * oi.unit_price_ron::bigint)
        FROM order_items oi
        JOIN orders o ON o.id = oi.order_id
        WHERE o.event_id = e.id AND o.status = 'completed'
    ), 0)::bigint AS total_revenue_ron,
    (SELECT COUNT(*)::bigint FROM event_rsvps r WHERE r.event_id = e.id AND r.status = 'interested') AS interested_count,
    (SELECT COUNT(*)::bigint FROM event_rsvps r WHERE r.event_id = e.id AND r.status = 'going' AND NOT EXISTS (
        SELECT 1 FROM tickets t
        JOIN orders o ON o.id = t.order_id
        JOIN ticket_types ticket_type ON ticket_type.id = t.ticket_type_id
        WHERE ticket_type.event_id = e.id AND o.status = 'completed' AND t.user_id = r.user_id
    ))
      + (SELECT COUNT(DISTINCT t.user_id)::bigint FROM tickets t JOIN orders o ON o.id = t.order_id JOIN ticket_types ticket_type ON ticket_type.id = t.ticket_type_id WHERE ticket_type.event_id = e.id AND o.status = 'completed' AND t.user_id IS NOT NULL) AS going_count,
    (SELECT COUNT(DISTINCT t.user_id)::bigint FROM tickets t JOIN orders o ON o.id = t.order_id JOIN ticket_types ticket_type ON ticket_type.id = t.ticket_type_id WHERE ticket_type.event_id = e.id AND o.status = 'completed' AND t.user_id IS NOT NULL) AS ticket_holder_count,
    COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', tt.id,
                'name', tt.name,
                'price_ron', tt.price_ron,
                'capacity', tt.capacity,
                'tickets_sold', tt.tickets_sold,
                'start_sales', tt.start_sales,
                'end_sales', tt.end_sales,
                'description', tt.description
            )
        ) FILTER (WHERE tt.id IS NOT NULL),
        '[]'::jsonb
    ) AS ticket_types,
    COALESCE(
        (
            SELECT json_agg(
                json_build_object(
                    'id', artist.id,
                    'name', artist.name,
                    'image_url', COALESCE(artist.image_url, ''),
                    'stage', artist.stage,
                    'performance_time', artist.performance_time,
                    'spotify_url', artist.spotify_url,
                    'is_headliner', artist.is_headliner,
                    'source', artist.source
                ) ORDER BY artist.sort_order, artist.created_at
            )
            FROM event_artists artist
            WHERE artist.event_id = e.id
        ),
        '[]'::json
    ) AS lineup
FROM events e
LEFT JOIN ticket_types tt ON tt.event_id = e.id
WHERE e.organizer_id = $1
GROUP BY e.id
ORDER BY e.start_time DESC
`

